use serde::{Deserialize,Serialize};use wasm_bindgen::prelude::*;
#[derive(Serialize,Deserialize,Clone)]#[serde(rename_all="camelCase")]pub struct Tier{pub up_to_kg:Option<f64>,pub rate_per_kg:f64}
#[derive(Serialize,Deserialize,Clone)]#[serde(rename_all="camelCase")]pub struct Card{pub id:String,pub corridor:String,pub currency:String,pub base_rate:f64,pub per_kg:f64,pub volumetric_divisor:f64,pub fuel_percent:f64,pub cess_flat:f64,pub handling_flat:f64,pub tiers:Vec<Tier>}
#[derive(Serialize,Deserialize)]#[serde(rename_all="camelCase")]pub struct Input{pub length_cm:f64,pub width_cm:f64,pub height_cm:f64,pub dead_weight_kg:f64,pub pieces:u32,pub declared_value:f64}
#[derive(Serialize,Deserialize)]#[serde(rename_all="camelCase")]pub struct Quote{pub volumetric_weight_kg:f64,pub dead_weight_kg:f64,pub chargeable_weight_kg:f64,pub base_charge:f64,pub fuel_surcharge:f64,pub cess:f64,pub handling:f64,pub subtotal:f64,pub total:f64,pub currency:String,pub corridor:String}
fn r(n:f64)->f64{(n*100.0).round()/100.0}fn valid(v:&[f64])->Result<(),String>{if v.iter().any(|x|!x.is_finite()||*x<0.0){Err("Values must be finite and non-negative".into())}else{Ok(())}}
pub fn calculate(c:&Card,i:&Input)->Result<Quote,String>{valid(&[i.length_cm,i.width_cm,i.height_cm,i.dead_weight_kg,i.declared_value,c.base_rate,c.per_kg,c.volumetric_divisor,c.fuel_percent,c.cess_flat,c.handling_flat])?;if i.pieces==0||c.volumetric_divisor<=0.0{return Err("Pieces and divisor must be greater than zero".into())}if c.fuel_percent>100.0{return Err("Fuel percentage cannot exceed 100".into())}let vol=i.length_cm*i.width_cm*i.height_cm*i.pieces as f64/c.volumetric_divisor;let charge=vol.max(i.dead_weight_kg);let rate=c.tiers.iter().filter(|t|t.up_to_kg.map(|n|charge<=n).unwrap_or(true)).min_by(|a,b|a.up_to_kg.unwrap_or(f64::INFINITY).total_cmp(&b.up_to_kg.unwrap_or(f64::INFINITY))).map(|t|t.rate_per_kg).unwrap_or(c.per_kg);valid(&[rate])?;let base=c.base_rate+charge*rate;let fuel=base*c.fuel_percent/100.0;let total=base+fuel+c.cess_flat+c.handling_flat;Ok(Quote{volumetric_weight_kg:r(vol),dead_weight_kg:r(i.dead_weight_kg),chargeable_weight_kg:r(charge),base_charge:r(base),fuel_surcharge:r(fuel),cess:r(c.cess_flat),handling:r(c.handling_flat),subtotal:r(total),total:r(total),currency:c.currency.clone(),corridor:c.corridor.clone()})}
#[derive(Serialize,Deserialize)]#[serde(rename_all="camelCase")]pub struct SplitInput{pub revenue:f64,pub carrier_percent:f64,pub fleet_percent:f64,pub depot_fee:f64,pub driver_advance:f64,pub carrier_paid:f64,pub fleet_paid:f64,pub depot_paid:f64,pub cost_basis:f64}
#[derive(Serialize)]#[serde(rename_all="camelCase")]pub struct Split{pub carrier_due:f64,pub fleet_due:f64,pub depot_due:f64,pub carrier_balance:f64,pub fleet_balance:f64,pub depot_balance:f64,pub total_allocated:f64,pub total_paid:f64,pub margin:f64,pub negative_margin:bool}
pub fn calculate_split(i:&SplitInput)->Result<Split,String>{valid(&[i.revenue,i.carrier_percent,i.fleet_percent,i.depot_fee,i.driver_advance,i.carrier_paid,i.fleet_paid,i.depot_paid,i.cost_basis])?;if i.carrier_percent+i.fleet_percent>100.0{return Err("Carrier and fleet shares exceed 100%".into())}let c=i.revenue*i.carrier_percent/100.0;let f=i.revenue*i.fleet_percent/100.0;let d=i.depot_fee;let m=i.revenue-c-f-d-i.cost_basis;Ok(Split{carrier_due:r(c),fleet_due:r(f),depot_due:r(d),carrier_balance:r((c-i.carrier_paid).max(0.0)),fleet_balance:r((f-i.fleet_paid).max(0.0)),depot_balance:r((d-i.depot_paid).max(0.0)),total_allocated:r(c+f+d),total_paid:r(i.carrier_paid+i.fleet_paid+i.depot_paid),margin:r(m),negative_margin:m<0.0})}
fn allowed(a:&str,b:&str)->bool{matches!((a,b),("Booked","In Transit")|("In Transit","At Hub")|("At Hub","In Transit")|("At Hub","Delivered")|("In Transit","Delivered"))}
#[wasm_bindgen]pub fn quote_tariff(card:JsValue,input:JsValue)->Result<JsValue,JsValue>{let c:Card=serde_wasm_bindgen::from_value(card).map_err(|e|JsValue::from_str(&e.to_string()))?;let i:Input=serde_wasm_bindgen::from_value(input).map_err(|e|JsValue::from_str(&e.to_string()))?;let q=calculate(&c,&i).map_err(|e|JsValue::from_str(&e))?;serde_wasm_bindgen::to_value(&q).map_err(|e|JsValue::from_str(&e.to_string()))}
#[wasm_bindgen]pub fn split_payouts(input:JsValue)->Result<JsValue,JsValue>{let i:SplitInput=serde_wasm_bindgen::from_value(input).map_err(|e|JsValue::from_str(&e.to_string()))?;let s=calculate_split(&i).map_err(|e|JsValue::from_str(&e))?;serde_wasm_bindgen::to_value(&s).map_err(|e|JsValue::from_str(&e.to_string()))}
#[wasm_bindgen]pub fn transition_shipment(current:&str,next:&str)->Result<bool,JsValue>{if allowed(current,next){Ok(true)}else{Err(JsValue::from_str("Invalid shipment status transition"))}}
#[wasm_bindgen]pub fn validate_rate_card(card:JsValue)->Result<bool,JsValue>{let c:Card=serde_wasm_bindgen::from_value(card).map_err(|e|JsValue::from_str(&e.to_string()))?;valid(&[c.base_rate,c.per_kg,c.volumetric_divisor,c.fuel_percent,c.cess_flat,c.handling_flat]).map_err(|e|JsValue::from_str(&e))?;if c.volumetric_divisor<=0.0||c.fuel_percent>100.0{return Err(JsValue::from_str("Invalid divisor or fuel percentage"))}Ok(true)}
#[cfg(test)]mod tests{use super::*;fn card()->Card{Card{id:"x".into(),corridor:"Nairobi-Mombasa".into(),currency:"KES".into(),base_rate:500.0,per_kg:40.0,volumetric_divisor:5000.0,fuel_percent:10.0,cess_flat:100.0,handling_flat:50.0,tiers:vec![]}}#[test]fn volumetric_wins(){let q=calculate(&card(),&Input{length_cm:100.0,width_cm:50.0,height_cm:40.0,dead_weight_kg:10.0,pieces:1,declared_value:0.0}).unwrap();assert_eq!(q.chargeable_weight_kg,40.0);assert_eq!(q.total,2460.0)}#[test]fn dead_weight_wins(){let q=calculate(&card(),&Input{length_cm:10.0,width_cm:10.0,height_cm:10.0,dead_weight_kg:25.0,pieces:1,declared_value:0.0}).unwrap();assert_eq!(q.chargeable_weight_kg,25.0)}#[test]fn status_rejects_skip(){assert!(!allowed("Booked","Delivered"));assert!(allowed("Booked","In Transit"))}#[test]fn payout_margin(){let s=calculate_split(&SplitInput{revenue:1000.0,carrier_percent:60.0,fleet_percent:20.0,depot_fee:100.0,driver_advance:0.0,carrier_paid:200.0,fleet_paid:0.0,depot_paid:0.0,cost_basis:300.0}).unwrap();assert!(s.negative_margin);assert_eq!(s.carrier_balance,400.0)}}